// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, address querier, uint256 amountDepositor, uint256 amountQuerier) public {
        vm.assume(depositor != address(0));
        vm.assume(querier != address(0));

        amountDepositor = bound(amountDepositor, 0, 1 ether);
        amountQuerier = bound(amountQuerier, 0, 1 ether);

        vm.deal(depositor, amountDepositor + 1 wei);
        vm.deal(querier, amountQuerier + 1 wei);

        if (amountDepositor > 0) {
            vm.prank(depositor);
            c.addToBalance{value: amountDepositor}();
        }

        if (amountQuerier > 0) {
            vm.prank(querier);
            c.addToBalance{value: amountQuerier}();
        }

        uint256 reported;
        vm.prank(querier);
        reported = c.getBalance(depositor);

        assertTrue(reported == amountDepositor);
    }
}
